class ListNode:
    def __init__(self, val: int = 0, next: "ListNode | None" = None) -> None:
        self.val = val
        self.next = next


class MyLinkedList:
    def __init__(self) -> None:
        # The dummy sits before the head, so every node has one before it.
        self.dummy = ListNode()
        self.size = 0

    # The node just before position index (the dummy for index 0).
    def _node_before(self, index: int) -> ListNode:
        node = self.dummy
        for _ in range(index):
            node = node.next
        return node

    def get(self, index: int) -> int:
        if index >= self.size:
            return -1
        return self._node_before(index).next.val

    def add_at_head(self, val: int) -> None:
        self.add_at_index(0, val)

    def add_at_tail(self, val: int) -> None:
        self.add_at_index(self.size, val)

    def add_at_index(self, index: int, val: int) -> None:
        if index > self.size:
            return
        before = self._node_before(index)
        before.next = ListNode(val, before.next)
        self.size += 1

    def delete_at_index(self, index: int) -> None:
        if index >= self.size:
            return
        before = self._node_before(index)
        before.next = before.next.next
        self.size -= 1


