struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x = 0, ListNode* next = nullptr) : val(x), next(next) {}
};

class MyLinkedList {
public:
    int get(int index) {
        if (index >= size_) {
            return -1;
        }
        return nodeBefore(index)->next->val;
    }

    void addAtHead(int val) {
        addAtIndex(0, val);
    }

    void addAtTail(int val) {
        addAtIndex(size_, val);
    }

    void addAtIndex(int index, int val) {
        if (index > size_) {
            return;
        }
        ListNode* before = nodeBefore(index);
        before->next = new ListNode(val, before->next);
        size_++;
    }

    void deleteAtIndex(int index) {
        if (index >= size_) {
            return;
        }
        ListNode* before = nodeBefore(index);
        before->next = before->next->next;
        size_--;
    }

private:
    ListNode dummy_;  // sits before the head, so every node has one before it
    int size_ = 0;

    // The node just before position index (the dummy for index 0).
