import "fmt"

type ListNode struct {
	Val  int
	Next *ListNode
}

// MyLinkedList is a singly linked list. Its dummy node sits before the head,
// so every node has one before it.
type MyLinkedList struct {
	dummy ListNode
	size  int
}

// nodeBefore returns the node just before position index (the dummy for 0).
func (l *MyLinkedList) nodeBefore(index int) *ListNode {
	node := &l.dummy
	for i := 0; i < index; i++ {
		node = node.Next
	}
	return node
}

func (l *MyLinkedList) get(index int) int {
	if index >= l.size {
		return -1
	}
	return l.nodeBefore(index).Next.Val
}

func (l *MyLinkedList) addAtHead(val int) {
	l.addAtIndex(0, val)
}

func (l *MyLinkedList) addAtTail(val int) {
	l.addAtIndex(l.size, val)
}

func (l *MyLinkedList) addAtIndex(index, val int) {
	if index > l.size {
		return
	}
	before := l.nodeBefore(index)
	before.Next = &ListNode{Val: val, Next: before.Next}
	l.size++
}

func (l *MyLinkedList) deleteAtIndex(index int) {
	if index >= l.size {
		return
	}
	before := l.nodeBefore(index)
	before.Next = before.Next.Next
	l.size--
}

func main() {
	var q int
	fmt.Scan(&q)
	linkedList := MyLinkedList{}
	for i := 0; i < q; i++ {
		var op string
