class ListNode {
  val: number;
  next: ListNode | null;

  constructor(val = 0, next: ListNode | null = null) {
    this.val = val;
    this.next = next;
  }
}

class MyLinkedList {
  // The dummy sits before the head, so every node has one before it.
  private dummy = new ListNode();
  private size = 0;

  // The node just before position index (the dummy for index 0).
  private nodeBefore(index: number): ListNode {
    let node = this.dummy;
    for (let i = 0; i < index && node.next !== null; i++) {
      node = node.next;
    }
    return node;
  }

  get(index: number): number {
    if (index >= this.size) {
      return -1;
    }
    return this.nodeBefore(index).next?.val ?? -1;
  }

  addAtHead(val: number): void {
    this.addAtIndex(0, val);
  }

  addAtTail(val: number): void {
    this.addAtIndex(this.size, val);
  }

  addAtIndex(index: number, val: number): void {
    if (index > this.size) {
      return;
    }
    const before = this.nodeBefore(index);
    before.next = new ListNode(val, before.next);
    this.size++;
  }

  deleteAtIndex(index: number): void {
    if (index >= this.size) {
      return;
    }
    const before = this.nodeBefore(index);
    before.next = before.next?.next ?? null;
    this.size--;
  }
}

